def semver_sort(versions):
    def parse(v):
        core = v.split('+', 1)[0]
        if '-' in core:
            main, pre = core.split('-', 1)
        else:
            main, pre = core, None
        major, minor, patch = (int(x) for x in main.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def cmp_pre(a, b):
        # a, b are lists of pre-release identifiers or None
        if a is None and b is None:
            return 0
        if a is None:
            return 1
        if b is None:
            return -1
        for x, y in zip(a, b):
            xd, yd = x.isdigit(), y.isdigit()
            if xd and yd:
                xi, yi = int(x), int(y)
                if xi != yi:
                    return -1 if xi < yi else 1
            elif xd and not yd:
                return -1
            elif not xd and yd:
                return 1
            else:
                if x != y:
                    return -1 if x < y else 1
        if len(a) != len(b):
            return -1 if len(a) < len(b) else 1
        return 0

    import functools

    def cmp(v1, v2):
        p1 = parse(v1)
        p2 = parse(v2)
        for i in range(3):
            if p1[i] != p2[i]:
                return -1 if p1[i] < p2[i] else 1
        return cmp_pre(p1[3], p2[3])

    return sorted(versions, key=functools.cmp_to_key(cmp))

